INSERT INTO agent_skills (organization_id, name, description, content, files, allowed_tools, is_enabled)
SELECT
  NULL,
  'finding-assessment-triage',
  'Assess scanner findings against product context so agents can hide noise and preserve durable markdown reasoning.',
  'Use this skill when reviewing durable scanner findings before they are shown to users. Treat scanner output as evidence, not product truth. Fetch the current open findings, inspect the mix of source kinds and repeated patterns, then decide your own batching and parallelization strategy. Use subagents or parallel workers when useful, but reconcile final verdicts yourself. Do not stop while there are currently open findings in scope without a proper markdown assessment note. For each finding, decide whether it is actionable, not relevant, false positive, accepted risk, needs context, or resolved candidate. Write concise markdown reasoning that explains why the issue should remain visible or be hidden. Be aggressive about suppressing findings for unused providers, managed platform/system resources, or generic benchmark checks with no product impact. Preserve raw evidence and uncertainty.',
  '[{"path":"README.md","content":"# Finding Assessment Triage\n\n## Purpose\n\nTurn raw scanner findings into product judgment before the human sees them.\n\n## Verdicts\n\n| Verdict | Meaning |\n| --- | --- |\n| actionable | Real, product-relevant, and should be shown. |\n| not_relevant | Real scanner condition but outside current product/runtime/scope. |\n| false_positive | Scanner claim appears wrong. |\n| accepted_risk | Real and relevant, but intentionally tolerated. |\n| needs_context | Missing a specific bridge or fact needed to decide. |\n| resolved_candidate | Evidence suggests this may be fixed, pending validation. |\n\n## Rules\n\n- Read the latest finding and prior assessments first.\n- Use product/wiki/runtime context to suppress scanner noise.\n- Do not create threat stories from noise.\n- Cite evidence refs, resource IDs, wiki paths, run IDs, and missing bridges.\n- Keep reasoning markdown durable and useful for a future agent.\n- Prefer `noise` importance for not_relevant and false_positive.\n"},{"path":"checklists/cloud-noise.md","content":"# Cloud Scanner Noise Checklist\n\nMark as likely noise when:\n\n- The provider/account is not used by the product runtime.\n- The asset is managed by the cloud provider or platform control plane.\n- The check is a generic benchmark item with no reachable service, identity, data path, or customer impact.\n- The resource is stale, test-only, or outside declared scope.\n\nKeep visible when:\n\n- It touches public ingress, workload identity, secrets, data stores, CI/CD, agent execution, customer data, or production namespaces.\n- It enables privilege escalation, exfiltration, tenant bypass, public exposure, or blast radius expansion.\n- The wiki or inventory says this resource is product-owned or on a deployment path.\n"}]'::jsonb,
  NULL,
  true
WHERE NOT EXISTS (
  SELECT 1 FROM agent_skills WHERE organization_id IS NULL AND name = 'finding-assessment-triage'
);
